#!/usr/bin/env python3
"""Remove the map and camera snapshots generated by the ROS 2 node."""
from __future__ import annotations

import argparse
import re
from pathlib import Path


REPO = Path(__file__).resolve().parents[1]
MAP_IMAGE = re.compile(r"(?:latest|frame_\d+)\.png")
CAMERA_IMAGE = re.compile(
    r"(?:latest_camera|latest_goal|camera_\d+(?:\.\d+)?|goal_\d+_\d+_node_\d+)\.jpg"
)


def clean_images(image_dir: Path) -> int:
    removed = 0
    for directory, pattern in ((image_dir, MAP_IMAGE), (image_dir / "camera", CAMERA_IMAGE)):
        if not directory.is_dir():
            continue
        for path in directory.iterdir():
            if path.is_file() and not path.is_symlink() and pattern.fullmatch(path.name):
                path.unlink()
                removed += 1
    return removed


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "image_dir", nargs="?", type=Path, default=REPO / "runs/ros2/map_images",
        help="map_image_dir used by the ROS node (default: runs/ros2/map_images)",
    )
    args = parser.parse_args()
    count = clean_images(args.image_dir.expanduser())
    print(f"Removed {count} generated image(s) from {args.image_dir}")


if __name__ == "__main__":
    main()
